// src/App.js
import React, { useState, useEffect, useRef } from 'react';
import * as THREE from 'three';
import LoginModal from './components/LoginModal';
import Chat from './components/Chat';
import './App.css';

function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [showChat, setShowChat] = useState(false);
  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);

  // Check for existing session on app load
  useEffect(() => {
    const checkAuth = () => {
      try {
        const storedUser = localStorage.getItem('user');
        const isLoggedIn = localStorage.getItem('isLoggedIn');

        if (storedUser && isLoggedIn === 'true') {
          const userData = JSON.parse(storedUser);
          setUser(userData);
          setShowChat(true);
        }
      } catch (error) {
        console.error('Auth check error:', error);
      } finally {
        setIsLoading(false);
      }
    };

    checkAuth();
  }, []);

  // Initialize THREE.js scene
  useEffect(() => {
    if (!mountRef.current || !user) return;

    // Setup scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x667eea);
    sceneRef.current = scene;

    // Setup camera
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 2, 5);
    cameraRef.current = camera;

    // Setup renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Add lights
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404040);
    scene.add(ambientLight);

    // Directional light
    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    scene.add(directionalLight);

    // Fill light from below
    const fillLight = new THREE.PointLight(0x4466cc, 0.3);
    fillLight.position.set(0, -2, 0);
    scene.add(fillLight);

    // Create a cube (example 3D object)
    const geometry = new THREE.BoxGeometry(1, 1, 1);
    const material = new THREE.MeshStandardMaterial({ color: 0xff6b6b, metalness: 0.3, roughness: 0.4 });
    const cube = new THREE.Mesh(geometry, material);
    cube.castShadow = true;
    cube.receiveShadow = true;
    scene.add(cube);

    // Create a floor
    const floorGeometry = new THREE.PlaneGeometry(10, 10);
    const floorMaterial = new THREE.MeshStandardMaterial({ color: 0x2c3e50, side: THREE.DoubleSide });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1;
    floor.receiveShadow = true;
    scene.add(floor);

    // Add a wireframe sphere
    const sphereGeometry = new THREE.SphereGeometry(0.8, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({ 
      color: 0x4ecdc4, 
      wireframe: true,
      transparent: true,
      opacity: 0.6
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(1.5, 0, -1);
    sphere.castShadow = true;
    scene.add(sphere);

    // Add a torus
    const torusGeometry = new THREE.TorusGeometry(0.6, 0.2, 16, 100);
    const torusMaterial = new THREE.MeshStandardMaterial({ color: 0xffe66d });
    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(-1.5, 0.2, -1);
    torus.castShadow = true;
    scene.add(torus);

    // Add particles
    const particlesGeometry = new THREE.BufferGeometry();
    const particlesCount = 1000;
    const posArray = new Float32Array(particlesCount * 3);

    for (let i = 0; i < particlesCount; i++) {
      posArray[i * 3] = (Math.random() - 0.5) * 20;
      posArray[i * 3 + 1] = (Math.random() - 0.5) * 10;
      posArray[i * 3 + 2] = (Math.random() - 0.5) * 15 - 5;
    }

    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
    const particlesMaterial = new THREE.PointsMaterial({
      size: 0.05,
      color: 0xffffff,
      transparent: true,
      opacity: 0.5
    });
    const particlesMesh = new THREE.Points(particlesGeometry, particlesMaterial);
    scene.add(particlesMesh);

    // Animation loop
    let time = 0;
    const animate = () => {
      requestAnimationFrame(animate);

      time += 0.01;

      // Rotate cube
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.01;

      // Bobbing sphere
      sphere.position.y = Math.sin(time) * 0.3;

      // Rotating torus
      torus.rotation.x += 0.02;
      torus.rotation.y += 0.03;

      // Rotating particles
      particlesMesh.rotation.y += 0.002;
      particlesMesh.rotation.x += 0.001;

      // Smooth camera follow
      camera.position.x += (0 - camera.position.x) * 0.05;
      camera.lookAt(0, 0, 0);

      renderer.render(scene, camera);
    };

    animate();

    // Handle window resize
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [user]);

  const handleLoginSuccess = (userData) => {
    console.log('Login successful:', userData);
    setUser(userData);
    setShowChat(true);
    setIsModalOpen(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isLoggedIn');
    setUser(null);
    setShowChat(false);
  };

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  // Show loading spinner while checking auth
  if (isLoading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading...</p>
      </div>
    );
  }

  return (
    <div className="App">
      {/* THREE.js Canvas Container */}
      <div ref={mountRef} className="canvas-container" />

      {/* Navigation Bar */}
      <nav className="navbar">
        <div className="nav-container">
          <div className="nav-logo">
            <h1>3D Dashboard</h1>
          </div>

          <div className="nav-menu">
            <a href="/" className="nav-link">Home</a>
            <a href="/dashboard" className="nav-link">Dashboard</a>
            {showChat && <a href="/chat" className="nav-link">Chat</a>}

            {user ? (
              <div className="user-menu">
                <span className="user-name">Welcome, {user.username}!</span>
                <button onClick={handleLogout} className="logout-btn">
                  Logout
                </button>
              </div>
            ) : (
              <button onClick={openModal} className="login-btn">
                Login / Register
              </button>
            )}
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="main-content">
        {user ? (
          <div className="dashboard">
            <div className="welcome-card glass-effect">
              <h2>Welcome back, {user.username}!</h2>
              <p>Experience the 3D interactive dashboard</p>

              <div className="user-info">
                <h3>Your Information:</h3>
                <div className="info-card">
                  <p><strong>Username:</strong> {user.username}</p>
                  {user.email && <p><strong>Email:</strong> {user.email}</p>}
                  <p><strong>User ID:</strong> {user.id}</p>
                  {user.createdAt && (
                    <p><strong>Member since:</strong> {new Date(user.createdAt).toLocaleDateString()}</p>
                  )}
                </div>
              </div>

              <div className="dashboard-actions">
                <button className="action-btn" onClick={() => setShowChat(!showChat)}>
                  {showChat ? 'Hide Chat' : 'Show Chat'}
                </button>
                <button className="action-btn">View Profile</button>
                <button className="action-btn">Settings</button>
                <button className="action-btn logout-action" onClick={handleLogout}>
                  Logout
                </button>
              </div>

              {/* Chat Component */}
              {showChat && (
                <div className="chat-wrapper">
                  <Chat user={user} />
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="hero-section">
            <div className="hero-content glass-effect">
              <h1>Welcome to 3D Dashboard</h1>
              <p>An immersive experience with Three.js</p>
              <button onClick={openModal} className="cta-button">
                Get Started
              </button>
            </div>

            <div className="features">
              <div className="feature-card glass-effect">
                <div className="feature-icon">🎨</div>
                <h3>3D Graphics</h3>
                <p>Interactive 3D scenes powered by Three.js</p>
              </div>

              <div className="feature-card glass-effect">
                <div className="feature-icon">💬</div>
                <h3>Real-time Chat</h3>
                <p>Connect with others using Socket.io</p>
              </div>

              <div className="feature-card glass-effect">
                <div className="feature-icon">🔒</div>
                <h3>Secure Auth</h3>
                <p>Protected authentication system</p>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-content">
          <p>&copy; 2026 3D Dashboard. All rights reserved.</p>
          <div className="footer-links">
            <a href="/privacy">Privacy Policy</a>
            <a href="/terms">Terms of Service</a>
            <a href="/help">Help</a>
          </div>
        </div>
      </footer>

      {/* Login Modal */}
      <LoginModal
        isOpen={isModalOpen}
        onClose={closeModal}
        onLoginSuccess={handleLoginSuccess}
      />
    </div>
  );
}

export default App;
